import {createWaveformGesture,waveformPosition,createWaveformLaneStore,writeWaveformPosition,stepWaveformPosition} from '@/components/nyc-tron/ui/components/forge/waveform-gesture';
import {useStore} from 'zustand';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import { useRef,useLayoutEffect } from "react";
import { PanResponder,Platform,View,type ViewProps,type ViewStyle } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import {
  FULL_RANGE,assertWaveformRange,peaksToBars,resamplePeaks,slicePeaks,
  type WaveformPeak,type WaveformRange,
} from "@/components/nyc-tron/ui/components/forge/waveform";


export interface WaveformLaneProps extends Omit<ViewProps,"children">,ScopedControlProps {
  /** Measured real source signal extrema; not synthetic waves. */
  readonly peaks:readonly WaveformPeak[];
  readonly columns?:number;
  readonly height?:number;
  readonly onSeekNormalized?:(position:number)=>void;
  /** Current playhead in [0, 1]; screen-reader steps move from here. */
  readonly position?:number;
  /** Normalized distance per accessibility increment/decrement. */
  readonly accessibilityStep?:number;
  /**
   * Part of the clip to draw, normalized. Only the peaks inside it are
   * resampled, so a zoomed-in view of a long clip costs the same as a short
   * one. @default FULL_RANGE
   */
  readonly visibleRange?:WaveformRange;
  /** Live preview of the range while the lane is dragged sideways. */
  readonly onVisibleRangeChange?:(range:WaveformRange)=>void;
  /**
   * Once per finished sideways drag. Without it the lane does not scroll and
   * every release seeks.
   */
  readonly onVisibleRangeCommit?:(range:WaveformRange)=>void;
  className?:string;
  barClassName?:string;
  unstyled?:boolean;
}

/**
 * Per-component import: no audio API, Forge engines, Skia or Nitro.
 * Bounded native view count (<=128) at any zoom: `visibleRange` picks the
 * window and only that window is resampled. A tap seeks; with
 * `onVisibleRangeCommit`, a sideways drag scrolls the window and commits
 * once on release. A GPU (Skia) lane for dense multitrack timelines is
 * deferred until that backend is verified on devices.
 */
export function WaveformLane({scope='waveform',revision=0,...props}:WaveformLaneProps){
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.disabledReason,props.visibleRange,props.columns,props.height]);
 if(props.peaks.length>1048576||props.peaks.some(p=>!Number.isFinite(p.min)||!Number.isFinite(p.max)||p.min>p.max||p.min< -1||p.max>1))throw new RangeError('Invalid waveform peaks');
 const guard=useScopedControl(owner,props,props.disabledReason!==undefined);
 return <View style={{minWidth:0}}><WaveformLaneBody sourceBoundary={JSON.stringify(controlIdentity(scope,revision))} gestureBoundary={owner} {...props}
  onSeekNormalized={props.onSeekNormalized?value=>{guard.current()?.onSeekNormalized?.(value);}:undefined}
  onVisibleRangeChange={props.onVisibleRangeChange?value=>{guard.current()?.onVisibleRangeChange?.(value);}:undefined}
  onVisibleRangeCommit={props.onVisibleRangeCommit?value=>guard.run('range',host=>host.onVisibleRangeCommit?.(value)):undefined}/>
  <ErrorMessage message={guard.error??props.disabledReason} unstyled={props.unstyled}/></View>;
}
function WaveformLaneBody({

  sourceBoundary,gestureBoundary,peaks,columns=96,height=64,onSeekNormalized,position,accessibilityStep=0.05,
  visibleRange=FULL_RANGE,onVisibleRangeChange,onVisibleRangeCommit,
  className,barClassName,unstyled=false,style,disabledReason,...props
}:WaveformLaneProps&{sourceBoundary:string;gestureBoundary:string}){
  assertWaveformRange(visibleRange);
  const width=useRef(0);
  const committedBoundary=useRef(gestureBoundary);
  const gesture=useRef<ReturnType<typeof createWaveformGesture>|null>(null);
  if(!gesture.current)gesture.current=createWaveformGesture();
  const session=gesture.current;
  const latest=useRef({onSeekNormalized,onVisibleRangeChange,onVisibleRangeCommit,visibleRange,sourceBoundary,position,accessibilityStep,disabled:disabledReason!==undefined});
  useLayoutEffect(()=>{latest.current={onSeekNormalized,onVisibleRangeChange,onVisibleRangeCommit,visibleRange,sourceBoundary,position,accessibilityStep,disabled:disabledReason!==undefined};});
  const local=useRef<ReturnType<typeof createWaveformLaneStore>|null>(null);
  if(!local.current)local.current=createWaveformLaneStore(visibleRange,sourceBoundary);
  const store=local.current;
  const active=useStore(store,s=>s.active);
  const previewRange=useStore(store,s=>s.range);
  const fallback=useStore(store,s=>s.fallback);
  const current=waveformPosition(position,sourceBoundary,fallback);
  const range=active?previewRange:visibleRange;
  useLayoutEffect(()=>{committedBoundary.current=gestureBoundary;session.cancel();store.setState({active:false});},[gestureBoundary,session,store]);
  useLayoutEffect(()=>()=>{session.cancel();},[session]);
  const seek=(next:number)=>{
    if(latest.current.disabled)return;
    const value=writeWaveformPosition(store,latest.current.sourceBoundary,next);
    latest.current.onSeekNormalized?.(value);
  };
  const responder=useRef<ReturnType<typeof PanResponder.create>|null>(null);
  if(!responder.current)responder.current=PanResponder.create({
    onStartShouldSetPanResponder:e=>(e.nativeEvent.touches?.length??1)<=1&&!latest.current.disabled&&(latest.current.onSeekNormalized!=null||latest.current.onVisibleRangeCommit!=null),
    onPanResponderGrant:e=>{if(latest.current.disabled||(e.nativeEvent.touches?.length??1)>1){session.cancel();store.setState({active:false});return;}session.begin(committedBoundary.current,width.current,latest.current.visibleRange);store.setState({active:false,range:latest.current.visibleRange});},
    onPanResponderMove:(_e,g)=>{
      const p=latest.current;if(p.disabled)return;
      if(g.numberActiveTouches>1){const scrolling=session.cancel();store.setState({active:false});if(scrolling)p.onVisibleRangeChange?.(p.visibleRange);return;}
      const next=session.move(committedBoundary.current,g.dx,p.onVisibleRangeCommit!=null);
      if(next){store.setState({active:true,range:next});p.onVisibleRangeChange?.(next);}
    },
    onPanResponderRelease:e=>{
      const result=session.release(committedBoundary.current,e.nativeEvent.locationX);
      store.setState({active:false});
      const p=latest.current;if(!result||p.disabled)return;
      if(result.kind==='range'){if(result.changed)p.onVisibleRangeCommit?.(result.range);}
      else if(p.onSeekNormalized)seek(result.position);
    },
    onPanResponderTerminate:()=>{
      const scrolling=session.cancel();store.setState({active:false});
      if(scrolling&&!latest.current.disabled)latest.current.onVisibleRangeChange?.(latest.current.visibleRange);
    },
    onPanResponderTerminationRequest:()=>!store.getState().active,
  });
  if(!Number.isFinite(accessibilityStep)||accessibilityStep<=0||accessibilityStep>1)
    throw new RangeError("accessibilityStep must be within (0, 1]");
  if(!Number.isInteger(columns)||columns<1||columns>128)
    throw new RangeError("Waveform columns must be 1..128");
  const bars=peaksToBars(resamplePeaks(slicePeaks(peaks,range),columns),height);
  const webTrack=Platform.OS==="web"&&onVisibleRangeCommit?{touchAction:"pan-y"} as unknown as ViewStyle:undefined;
  return <View
    {...props}
    {...responder.current.panHandlers}
    {...{className:joinClasses("w-full flex-row overflow-hidden",!unstyled&&"bg-surface-sunken",className)}}
    style={[{height,direction:"ltr"},webTrack,style]}
    accessible
    accessibilityRole={onSeekNormalized?"adjustable":"image"}
    accessibilityLabel={props.accessibilityLabel??"Audio waveform"}
    accessibilityState={{disabled:disabledReason!==undefined}}
    onLayout={e=>{if(committedBoundary.current!==gestureBoundary)return;const next=e.nativeEvent.layout.width;if(next!==width.current){const scrolling=session.cancel();store.setState({active:false});if(scrolling&&!latest.current.disabled)latest.current.onVisibleRangeChange?.(latest.current.visibleRange);width.current=Number.isFinite(next)&&next>0?next:0;}props.onLayout?.(e);}}
    accessibilityValue={onSeekNormalized?{min:0,max:100,now:Math.round(current*100)}:undefined}
    accessibilityActions={onSeekNormalized?[{name:"increment"},{name:"decrement"}]:undefined}
    onAccessibilityAction={onSeekNormalized?e=>{
      if(committedBoundary.current!==gestureBoundary||latest.current.disabled||!latest.current.onSeekNormalized)return;
      // Step from the playhead; jumping to 0 or 1 would discard the position.
      const delta=e.nativeEvent.actionName==="increment"?latest.current.accessibilityStep:e.nativeEvent.actionName==="decrement"?-latest.current.accessibilityStep:0;
      if(delta){const p=latest.current;const value=stepWaveformPosition(store,{source:p.sourceBoundary,...(p.position===undefined?{}:{position:p.position})},delta);p.onSeekNormalized?.(value);}
    }:undefined}
  >{bars.map((bar,i)=><View key={i} style={{flex:1,height}}>
    <View
      {...{className:joinClasses("self-center w-3/4",!unstyled&&"bg-accent",barClassName)}}
      style={{marginTop:bar.top,height:bar.height}}
    />
  </View>)}</View>;
}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {createStore} from 'zustand/vanilla';
import {rangePosition,scrollRange,type WaveformRange} from '@/components/nyc-tron/ui/components/forge/waveform';
/** A gesture owns the coordinates/range captured at grant; cancellation consumes release. */
export function createWaveformGesture(){
 let gesture:{boundary:string;width:number;range:WaveformRange;preview:WaveformRange|null}|null=null;
 return {
  begin(boundary:string,width:number,range:WaveformRange){gesture=Number.isFinite(width)&&width>0?{boundary,width,range:{...range},preview:null}:null;},
  cancel(){const scrolling=gesture?.preview!=null;gesture=null;return scrolling;},
  move(boundary:string,dx:number,canScroll:boolean){
   if(!gesture||gesture.boundary!==boundary||!canScroll||!Number.isFinite(dx)||gesture.preview===null&&Math.abs(dx)<6)return null;
   const next=scrollRange(gesture.range,dx,gesture.width);
   if(gesture.preview&&gesture.preview.start===next.start&&gesture.preview.end===next.end)return null;
   gesture.preview=next;return next;
  },
  release(boundary:string,x:number){
   const previous=gesture;gesture=null;
   if(!previous||previous.boundary!==boundary||!Number.isFinite(x))return null;
   return previous.preview?{kind:'range' as const,range:previous.preview,changed:previous.preview.start!==previous.range.start}:{kind:'seek' as const,position:rangePosition(previous.range,x,previous.width)};
  },
 };
}
/** Read synchronously during render; no post-render reset can expose another source's caret. */
export function waveformPosition(position:number|undefined,source:string,last:{source:string;value:number}){
 return position!==undefined&&Number.isFinite(position)?Math.min(1,Math.max(0,position)):last.source===source?last.value:0;
}

export function createWaveformLaneStore(range:WaveformRange,source:string){
 return createStore(()=>({active:false,range,fallback:{source,value:0}}));
}
export function writeWaveformPosition(store:ReturnType<typeof createWaveformLaneStore>,source:string,next:number){
 const value=Math.min(1,Math.max(0,next));store.setState({fallback:{source,value}});return value;
}
/** Reads and writes the actual store synchronously, including between React renders. */
export function stepWaveformPosition(store:ReturnType<typeof createWaveformLaneStore>,authority:{source:string;position?:number},delta:number){
 return writeWaveformPosition(store,authority.source,waveformPosition(authority.position,authority.source,store.getState().fallback)+delta);
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
